import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { Form, Button, Col, Row, Alert } from "react-bootstrap";
import axios from "axios";
import AddIngredient from "../AddIngredient/AddIngredient";

function EditRecipe() {
  const { id } = useParams(); // recipeId aus URL
  const navigate = useNavigate();

  const [errorMsg, setErrorMsg] = useState("");
  const [successMsg, setSuccessMsg] = useState("");
  const [listId, setListId] = useState(1);

  const [formData, setFormData] = useState({
    name: "",
    description: "",
    imageUrl: "",
    ingredients: [],
    id: null,
  });

  // 🔹 Rezept laden
  useEffect(() => {
    const loadRecipe = async () => {
      try {
        const res = await axios.get(`http://127.0.0.1:8080/api/recipes/recipe/${id}`);
        const recipe = res.data;

        const ingredientsWithIds = (recipe.ingredients || []).map((ing, index) => ({
          ...ing,
          listId: index + 1,
        }));

        setListId(ingredientsWithIds.length + 1);

        setFormData({
          ...recipe,
          ingredients: ingredientsWithIds,
        });
      } catch (err) {
        setErrorMsg("Failed to load recipe");
      }
    };

    loadRecipe();
  }, [id]);

  const addIngredient = () => {
    setFormData((prev) => ({
      ...prev,
      ingredients: [
        ...prev.ingredients,
        {
          listId,
          ingredient: "",
          unit: "PIECE",
          quantity: "",
        },
      ],
    }));
    setListId((prev) => prev + 1);
  };

  const updateIngredient = (ingredientObj) => {
    setFormData((prev) => ({
      ...prev,
      ingredients: prev.ingredients.map((ing) =>
        ing.listId === ingredientObj.listId ? ingredientObj : ing
      ),
    }));
  };

  const removeIngredient = (ingredientObj) => {
    setFormData((prev) => ({
      ...prev,
      ingredients: prev.ingredients.filter(
        (ing) => ing.listId !== ingredientObj.listId
      ),
    }));
  };

  const handleUpdate = async (e) => {
    e.preventDefault();
    setErrorMsg("");
    setSuccessMsg("");

    const payload = {
      ...formData,
      ingredients: formData.ingredients.map(({ listId, ...rest }) => rest),
    };

    try {
      await axios.put(`http://127.0.0.1:8080/api/recipes/${id}`, payload, {
        headers: { "Content-Type": "application/json" },
      });

      setSuccessMsg("Recipe updated successfully!");
      setTimeout(() => navigate("/"), 1200);
    } catch (err) {
      setErrorMsg("Update failed");
    }
  };

  return (
    <div className="bg">
      <div className="m-3">
        <h1 className="h3 bg-dark text-bg-primary mt-2">Edit Recipe</h1>

        {errorMsg && <Alert variant="danger">{errorMsg}</Alert>}
        {successMsg && <Alert variant="success">{successMsg}</Alert>}

        <Form onSubmit={handleUpdate}>
          <Form.Group className="mb-1">
            <Form.Label>Name</Form.Label>
            <Form.Control
              value={formData.name}
              onChange={(e) =>
                setFormData((p) => ({ ...p, name: e.target.value }))
              }
            />
          </Form.Group>

          <Form.Group className="mb-1">
            <Form.Label>Description</Form.Label>
            <Form.Control
              value={formData.description}
              onChange={(e) =>
                setFormData((p) => ({ ...p, description: e.target.value }))
              }
            />
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label>Image URL</Form.Label>
            <Form.Control
              value={formData.imageUrl}
              onChange={(e) =>
                setFormData((p) => ({ ...p, imageUrl: e.target.value }))
              }
            />
          </Form.Group>

          <Row>
            <Col>Ingredient</Col>
            <Col>Unit</Col>
            <Col>Quantity</Col>
            <Col xs={1}></Col>
          </Row>

          <hr />

          {formData.ingredients.map((ingredient) => (
            <AddIngredient
              key={ingredient.listId}
              ingredient={ingredient}
              listId={listId - 1}
              updateIngredient={updateIngredient}
              removeIngredient={removeIngredient}
            />
          ))}

          <Button
            variant="warning"
            type="button"
            className="mt-2"
            onClick={addIngredient}
          >
            Add Ingredient
          </Button>

          <Button variant="primary" type="submit" className="mb-5 mt-3">
            Save Changes
          </Button>
        </Form>
      </div>
    </div>
  );
}

export default EditRecipe;
